def minimumSubarrayLength(nums: list[int], k: int) -> int:
    n = len(nums)
    ans = float('inf')
    for i in range(n):
        curr_or = 0
        for j in range(i, n):
            curr_or |= nums[j]
            if curr_or >= k:
                ans = min(ans, j - i + 1)
                break
    return ans if ans != float('inf') else -1

